import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.BvlN9b-o.js";const h=JSON.parse('{"title":"Build your SaaS with Dougong","description":"","frontmatter":{"docLocale":"en","counterpart":"/docs/","contentType":"overview","prev":false,"next":{"text":"Create your project","link":"/en/getting-started/create-project"}},"headers":[],"relativePath":"en/docs/index.md","filePath":"en/docs/index.md"}'),o={name:"en/docs/index.md"};function i(r,e,d,c,l,u){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="build-your-saas-with-dougong" tabindex="-1">Build your SaaS with Dougong <a class="header-anchor" href="#build-your-saas-with-dougong" aria-label="Permalink to &quot;Build your SaaS with Dougong&quot;">​</a></h1><p>Start with a Rust + Axum backend. Implement your business module, connect identity, persistence, audit, files and jobs, then deliver an API you can verify and deploy.</p><div class="docs-paths"><a class="docs-path" href="../learn/"><strong>Build a new business</strong><span>Develop a ticket SaaS backend with data, permissions, files and background jobs.</span></a><a class="docs-path" href="../architecture/project-structure"><strong>Experienced developer</strong><span>Find code ownership, then enter the database, endpoint, use case and testing guides.</span></a><a class="docs-path" href="../reference/api"><strong>Using the framework</strong><span>Look up public API, configuration, module integration and commands.</span></a></div><h2 id="framework-and-business-responsibilities" tabindex="-1">Framework and business responsibilities <a class="header-anchor" href="#framework-and-business-responsibilities" aria-label="Permalink to &quot;Framework and business responsibilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Framework capability</th><th>Your business owns</th></tr></thead><tbody><tr><td>Identity, sessions, membership and organization roles</td><td>Entities, rules and resource access</td></tr><tr><td>Settings, pools, migration entry and public errors</td><td>Use cases, transactions and HTTP contracts</td></tr><tr><td>Audit, idempotency, files, jobs, notifications and mail</td><td>Audit meaning, file ownership and business Handlers</td></tr><tr><td>OpenAPI, generated SDK, testing and deployment</td><td>Business checks, production configuration and operations</td></tr></tbody></table><p>Each deployment serves one Organization with multiple members and business resources. Sharing a deployment across customer organizations needs a new organization context and access contract; see the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/adr/0001-single-organization-deployment.md" target="_blank" rel="noreferrer">deployment decision</a>.</p><h2 id="understand-a-business-request" tabindex="-1">Understand a business request <a class="header-anchor" href="#understand-a-business-request" aria-label="Permalink to &quot;Understand a business request&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP / request DTO</span></span>
<span class="line"><span>  → your business use case</span></span>
<span class="line"><span>  → Core public capabilities and transaction</span></span>
<span class="line"><span>  → PostgreSQL / Platform adapters</span></span>
<span class="line"><span>  → response DTO / OpenAPI</span></span></code></pre></div><p>The application composes Router and OpenAPI, your module owns rules and tables, Core provides reusable SaaS capabilities, and Platform encapsulates infrastructure. See <a href="./../architecture/project-structure">project structure</a> and <a href="./../architecture/boundaries">Core and business boundaries</a>.</p><h2 id="run-then-develop" tabindex="-1">Run, then develop <a class="header-anchor" href="#run-then-develop" aria-label="Permalink to &quot;Run, then develop&quot;">​</a></h2><p>Prepare the tools in the <a href="./../getting-started/quickstart">quick start</a>, then build <code>tickets</code> in an isolated copy with the <a href="./../learn/">ticket SaaS course</a>. Four checkpoints provide complete runnable code. Ten lessons follow one business through persistence, protocols, authorization, transactions, files, jobs, verification and deployment. <a href="./../guides/new-module">Add a business module</a> is the concise integration guide.</p><p>Guides provide locations, public interfaces, minimal code, observable results and failure boundaries. Generated <a href="./../reference/api">API</a> and <a href="./../reference/config">configuration</a> keep the implementation as their source of truth.</p><h2 id="inspect-a-complete-implementation" tabindex="-1">Inspect a complete implementation <a class="header-anchor" href="#inspect-a-complete-implementation" aria-label="Permalink to &quot;Inspect a complete implementation&quot;">​</a></h2><p>The built-in knowledge example combines CRUD, resource grants, attachments, exports, notifications and audit. Learn how it calls Core, then replace the rules with your own business. Inspect <a href="./../tutorials/personal-documents">document use cases</a>, <a href="./../tutorials/library-grants">resource permissions</a> and <a href="./../tutorials/document-exports">background exports</a> for complete paths.</p><h2 id="clients-and-contributions" tabindex="-1">Clients and contributions <a class="header-anchor" href="#clients-and-contributions" aria-label="Permalink to &quot;Clients and contributions&quot;">​</a></h2><p>After the backend contract works, use <a href="./../tutorials/electron-shell">shared clients</a> and <a href="./../tutorials/add-example">business contributions</a> to connect Web and Electron. Chinese and English chapters stay paired during language switching. Search covers public documentation only.</p><p>Read the <a href="./../guides/documentation">author guide</a> when changing documentation and the <a href="./../getting-started/publish-docs">publishing guide</a> to publish your own site.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/getting-started/documentation.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,19)])])}const b=a(o,[["render",i]]);export{h as __pageData,b as default};
